  "implementation": "def solve(case):
    import json

    # Validate required top-level keys
    if not isinstance(case, dict):
        raise ValueError("case must be a dict")
    for key in ["min_cluster_size", "clusters", "parent"]:
        if key not in case:
            raise ValueError(f"Missing required key: {key}")
    min_cluster_size = case["min_cluster_size"]
    if not isinstance(min_cluster_size, (int, float)) or min_cluster_size < 0:
        raise ValueError("min_cluster_size must be a non-negative number")
    min_cluster_size = int(min_cluster_size)

    clusters_raw = case["clusters"]
    if not isinstance(clusters_raw, list):
        raise ValueError("clusters must be a list")

    parent = case["parent"]
    if not isinstance(parent, dict):
        raise ValueError("parent must be a dict")

    # Build cluster map and validate each cluster
    cluster_map = {}
    for cl in clusters_raw:
        if not isinstance(cl, dict):
            raise ValueError("each cluster must be a dict")
        for key in ["cluster_id", "size", "birth_lambda", "point_exit_lambdas"]:
            if key not in cl:
                raise ValueError(f"Cluster missing key: {key}")
        cid = cl["cluster_id"]
        if not isinstance(cid, str):
            raise ValueError("cluster_id must be a string")
        size = cl["size"]
        if not isinstance(size, int) or size < 0:
            raise ValueError("size must be a non-negative integer")
        birth = cl["birth_lambda"]
        if not isinstance(birth, (int, float)):
            raise ValueError("birth_lambda must be numeric")
        exits = cl["point_exit_lambdas"]
        if not isinstance(exits, list) or len(exits) != size:
            raise ValueError("point_exit_lambdas must be a list with length equal to size")
        for e in exits:
            if not isinstance(e, (int, float)):
                raise ValueError("each exit_lambda must be numeric")
        cluster_map[cid] = cl

    # Validate parent keys correspond to cluster_ids
    for cid in parent:
        if cid not in cluster_map:
            raise ValueError(f"parent key {cid} not in clusters")
        p = parent[cid]
        if p is not None and p not in cluster_map:
            raise ValueError(f"parent value {p} not in clusters")

    # Filter clusters by size
    retained_ids = {cid for cid, cl in cluster_map.items() if cl["size"] >= min_cluster_size}

    # Compute stability for each retained cluster
    stability_map = {}
    for cid in retained_ids:
        cl = cluster_map[cid]
        birth = cl["birth_lambda"]
        exits = cl["point_exit_lambdas"]
        stability = sum(max(0, e - birth) for e in exits)
        stability_map[cid] = stability

    # Build tree among retained clusters
    children = {cid: [] for cid in retained_ids}
    for cid in retained_ids:
        p = parent.get(cid)
        if p is not None and p in retained_ids:
            children[p].append(cid)

    # Helper to get all retained ancestors (including immediate parent up to root)
    def get_ancestors(cid):
        ancestors = []
        cur = cid
        while True:
            p = parent.get(cur)
            if p is None:
                break
            if p in retained_ids:
                ancestors.append(p)
            cur = p
        return ancestors

    # Helper to check if any descendant is selected
    def has_selected_descendant(cid, selected):
        stack = [cid]
        while stack:
            node = stack.pop()
            for child in children[node]:
                if child in selected:
                    return True
                stack.append(child)
        return False

    # Sort retained clusters by stability descending, then cluster_id ascending
    sorted_clusters = sorted(retained_ids, key=lambda cid: (-stability_map[cid], cid))

    selected = set()
    blocked = set()

    for cid in sorted_clusters:
        if cid in blocked:
            continue
        if has_selected_descendant(cid, selected):
            continue
        selected.add(cid)
        # Block all ancestors
        for anc in get_ancestors(cid):
            blocked.add(anc)

    # Build output
    clusters_out = []
    for cid in sorted(retained_ids):  # sort by cluster_id for deterministic order
        cl = cluster_map[cid]
        clusters_out.append({
            "cluster_id": cid,
            "size": cl["size"],
            "stability": stability_map[cid]
        })

    selected_ids = sorted(selected)  # ascending string order

    return {
        "clusters": clusters_out,
        "selected_cluster_ids": selected_ids
    }"
}
